/*
 * sales-tool.js — core logic for the local Sales CSV tool.
 *
 * Dual-use: the browser page (window.SalesTool) and Node tests
 * (require("./sales-tool.js")) run the exact same code.
 *
 * Input contract: a CSV with the columns month, region, revenue
 * (any column order; header names matched case-insensitively).
 *  - month   : "YYYY-MM" (also accepts 2026/1, 2026-1-15 -> 2026-01)
 *  - region  : free text
 *  - revenue : number; "$1,234.50" and "(500)" are tolerated
 */
(function (root, factory) {
  if (typeof module === "object" && module.exports) {
    module.exports = factory();
  } else {
    root.SalesTool = factory();
  }
})(typeof self !== "undefined" ? self : this, function () {
  "use strict";

  var EXPECTED_COLUMNS = ["month", "region", "revenue"];

  /* --- CSV parsing (RFC 4180 subset: quotes, "" escapes, CRLF, BOM) --- */
  function parseCsv(text) {
    var rows = [];
    var row = [];
    var field = "";
    var inQuotes = false;
    var i = text.charCodeAt(0) === 0xfeff ? 1 : 0; // skip BOM
    while (i < text.length) {
      var ch = text.charAt(i);
      if (inQuotes) {
        if (ch === '"') {
          if (text.charAt(i + 1) === '"') { field += '"'; i += 2; continue; }
          inQuotes = false; i += 1; continue;
        }
        field += ch; i += 1; continue;
      }
      if (ch === '"') { inQuotes = true; i += 1; continue; }
      if (ch === ",") { row.push(field); field = ""; i += 1; continue; }
      if (ch === "\r") { i += 1; continue; } // \r\n or stray \r
      if (ch === "\n") { row.push(field); rows.push(row); row = []; field = ""; i += 1; continue; }
      field += ch; i += 1;
    }
    if (field !== "" || row.length > 0) { row.push(field); rows.push(row); }
    return rows;
  }

  function normalizeMonth(value) {
    var s = String(value).trim();
    var m = s.match(/^(\d{4})[-/](\d{1,2})(?:[-/]\d{1,2})?$/);
    if (m) return m[1] + "-" + ("0" + m[2]).slice(-2);
    return s;
  }

  function parseRevenue(value) {
    var s = String(value).trim();
    if (s === "") return NaN;
    s = s.replace(/[$€£¥,\s]/g, "");
    if (/^\(.*\)$/.test(s)) s = "-" + s.slice(1, -1); // accounting negatives
    return Number(s);
  }

  function round2(n) {
    return Math.round(n * 100) / 100;
  }

  /* --- Load + validate a dataset. Returns {rows, errors}; throws on fatal. --- */
  function loadDataset(text) {
    var rawRows = parseCsv(text);
    var errors = [];
    if (rawRows.length === 0) throw new Error("The file is empty.");

    var header = rawRows[0].map(function (h) { return h.trim().toLowerCase(); });
    var colIndex = {};
    for (var c = 0; c < EXPECTED_COLUMNS.length; c++) {
      var name = EXPECTED_COLUMNS[c];
      var idx = header.indexOf(name);
      if (idx === -1) {
        throw new Error('Missing required column "' + name + '". Found header: ' + rawRows[0].join(", "));
      }
      colIndex[name] = idx;
    }

    var rows = [];
    for (var r = 1; r < rawRows.length; r++) {
      var cells = rawRows[r];
      if (cells.length === 1 && cells[0].trim() === "") continue; // blank line
      var lineNo = r + 1;
      if (cells.length < header.length) {
        errors.push("Row " + lineNo + ": expected " + header.length + " fields, got " + cells.length + " — skipped.");
        continue;
      }
      var month = normalizeMonth(cells[colIndex.month]);
      var region = String(cells[colIndex.region]).trim();
      var revenue = parseRevenue(cells[colIndex.revenue]);
      if (month === "") { errors.push("Row " + lineNo + ": missing month — skipped."); continue; }
      if (region === "") { errors.push("Row " + lineNo + ": missing region — skipped."); continue; }
      if (!isFinite(revenue)) {
        errors.push('Row ' + lineNo + ': revenue "' + cells[colIndex.revenue] + '" is not a number — skipped.');
        continue;
      }
      rows.push({ month: month, region: region, revenue: revenue });
    }

    if (rows.length === 0) {
      throw new Error("No valid data rows were found." + (errors.length ? " First problem: " + errors[0] : ""));
    }
    return { rows: rows, errors: errors };
  }

  function uniqueRegions(rows) {
    var seen = {};
    var out = [];
    rows.forEach(function (row) {
      if (!seen.hasOwnProperty(row.region)) { seen[row.region] = true; out.push(row.region); }
    });
    return out.sort();
  }

  /* region === null (or "All regions") keeps everything. */
  function filterByRegion(rows, region) {
    if (region === null || region === undefined || region === "All regions") return rows.slice();
    return rows.filter(function (row) { return row.region === region; });
  }

  /* [{month, revenue}] sorted by month, rounded to cents. */
  function monthlyRevenue(rows) {
    var byMonth = {};
    var months = [];
    rows.forEach(function (row) {
      if (!byMonth.hasOwnProperty(row.month)) { byMonth[row.month] = 0; months.push(row.month); }
      byMonth[row.month] += row.revenue;
    });
    months.sort();
    return months.map(function (m) { return { month: m, revenue: round2(byMonth[m]) }; });
  }

  function regionTotals(rows) {
    var byRegion = {};
    uniqueRegions(rows).forEach(function (region) { byRegion[region] = 0; });
    rows.forEach(function (row) { byRegion[row.region] += row.revenue; });
    return Object.keys(byRegion).sort().map(function (r) {
      return { region: r, revenue: round2(byRegion[r]) };
    });
  }

  function totalRevenue(rows) {
    var sum = 0;
    rows.forEach(function (row) { sum += row.revenue; });
    return round2(sum);
  }

  function csvEscape(value) {
    var s = String(value);
    if (/[",\n\r]/.test(s)) s = '"' + s.replace(/"/g, '""') + '"';
    return s;
  }

  function toCsv(rows) {
    var lines = ["month,region,revenue"];
    rows.forEach(function (row) {
      lines.push([csvEscape(row.month), csvEscape(row.region), csvEscape(row.revenue)].join(","));
    });
    return lines.join("\n") + "\n";
  }

  return {
    EXPECTED_COLUMNS: EXPECTED_COLUMNS,
    parseCsv: parseCsv,
    normalizeMonth: normalizeMonth,
    parseRevenue: parseRevenue,
    loadDataset: loadDataset,
    uniqueRegions: uniqueRegions,
    filterByRegion: filterByRegion,
    monthlyRevenue: monthlyRevenue,
    regionTotals: regionTotals,
    totalRevenue: totalRevenue,
    toCsv: toCsv
  };
});
